import{_ as a,c as o,o as i,a9 as t,ao as n}from"./chunks/framework.C3PHgg-M.js";const p=JSON.parse('{"title":"Command","description":"How to add a command to a PURISTA typescript framework service","frontmatter":{"title":"Command","description":"How to add a command to a PURISTA typescript framework service","order":202000},"headers":[],"relativePath":"handbook/2_building_business-logic/command/index.md","filePath":"handbook/2_building_business-logic/command/index.md","lastUpdated":1778094759000}'),l={name:"handbook/2_building_business-logic/command/index.md"};function s(r,e,c,d,m,h){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="command" tabindex="-1">Command <a class="header-anchor" href="#command" aria-label="Permalink to “Command”">​</a></h1><p><img src="'+n+'" alt="Add command with cli"></p><p>A command is a single function, which will be called (invoked) by someone with the expectation to get a result back.</p><p>Add a command to an existing service with <code>purista add command</code>.</p><p>Commands can access service resources (for example database clients/connections) via <code>context.resources</code>. Resources are provided when creating the service instance with <code>serviceBuilder.getInstance(eventBridge, { resources: ... })</code>. Commands can also consume stream endpoints via <code>context.stream</code> when declared with <code>.canConsumeStream(...)</code>.</p><h2 id="command-lifecycle" tabindex="-1">Command lifecycle <a class="header-anchor" href="#command-lifecycle" aria-label="Permalink to “Command lifecycle”">​</a></h2><ol><li>optional input transform</li><li>payload/parameter validation</li><li>before guards</li><li>command function execution</li><li>output validation</li><li>after guards</li><li>optional output transform</li></ol><h2 id="what-to-read-next" tabindex="-1">What to read next <a class="header-anchor" href="#what-to-read-next" aria-label="Permalink to “What to read next”">​</a></h2><ul><li><a href="./the-command-builder.html">The command builder</a></li><li><a href="./invoke_command_from_command.html">Invoke another command</a></li><li><a href="./exposing-a-command-as-http-endpoint.html">Expose as HTTP endpoint</a></li><li><a href="./test-a-command.html">Test a command</a></li></ul><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to use”">​</a></h2><ul><li>You need request/response behavior.</li><li>A caller expects success/error result semantics.</li><li>You want strict validation on input/output contracts.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to “Common pitfalls”">​</a></h2><ul><li>mixing long-running asynchronous workflows into one command</li><li>overusing broad payload schemas instead of explicit contracts</li><li>forgetting to define output schema, then losing type guarantees</li></ul><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to “Checklist”">​</a></h2><ul><li>payload, parameter and output schemas are defined</li><li>guards are used for auth/authz concerns</li><li>command is exposed (or intentionally internal only)</li><li>unit tests cover success and failure paths</li></ul>',15)])])}const f=a(l,[["render",s]]);export{p as __pageData,f as default};
